from __future__ import annotations

import os
import sys
from pathlib import Path

_ROOT = Path(sys.executable).resolve().parent
_RUNTIME = _ROOT / "_runtime"
os.environ["UA_FREE_PORTABLE_ROOT"] = str(_ROOT)
os.environ["PYTHONNOUSERSITE"] = "1"
os.environ.setdefault("TCL_LIBRARY", str(_RUNTIME / "tcl" / "tcl8.6"))
os.environ.setdefault("TK_LIBRARY", str(_RUNTIME / "tcl" / "tk8.6"))

# The renamed launcher starts the GUI only for a normal double-click. Child
# Python invocations used for Codex installation remain ordinary Python runs.
if (
    Path(sys.executable).name.casefold() == "ua_free_content_tool.exe"
    and len(sys.argv) == 1
    and os.environ.get("UA_FREE_CHILD_PROCESS") != "1"
):
    from content_agent.main import main
    raise SystemExit(main())
